```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH p AS (SELECT 'abn' src, c.service_name caller, s.service_name callee, c.duration cd, s.duration sd FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' UNION ALL SELECT 'norm', c.service_name, s.service_name, c.duration, s.duration FROM normal_traces c JOIN normal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id AND c.attr_span_kind='Client' AND s.attr_span_kind='Server') SELECT src, caller, callee, count(*) n, approx_quantile((cd-sd)/1e6,0.5) gap_p50_ms, approx_quantile(cd/1e6,0.5) client_p50_ms, approx_quantile(sd/1e6,0.5) server_p50_ms FROM p WHERE caller='search' AND callee='rate' GROUP BY ALL ORDER BY src",
          "claim": "search->rate client spans take about 1743 ms at p50 with ~1742 ms gap, versus ~1.7 ms normal; rate server time stays ~0.13 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates') GROUP BY 1,2,3 ORDER BY 3,1",
          "claim": "rate's own GetRates server spans keep a p95 near 1 ms during the incident, so rate's processing is not slow."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, avg(value) avgv, max(value) maxv FROM abnormal_metrics_sum WHERE service_name='rate' AND metric IN ('k8s.pod.network.io','k8s.pod.cpu.usage','k8s.pod.uptime') GROUP BY ALL",
          "claim": "rate pod CPU, network volume and uptime show no saturation, restart or new pod during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, date_trunc('minute', c.time) m, count(*) n, approx_quantile((c.duration-s.duration)/1e6,0.5) gap_p50_ms, approx_quantile(s.duration/1e6,0.5) rate_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='search' AND s.service_name='rate' GROUP BY ALL ORDER BY m",
          "claim": "Every minute of the incident, the search-to-rate gap is about 1.6-1.9 s while rate's server time stays under 1.2 ms."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) client_p50_ms, approx_quantile(s.duration/1e6,0.5) server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='frontend' AND s.service_name='search' GROUP BY ALL",
          "claim": "frontend-to-search calls take about 1783 ms at p50, matching search's server time; the gap on this edge stays normal."
        }
      ]
    }
  ]
}
```

